// main_server.cpp
// Starts the Sunrise Cinema web server.
// Usage (run from the project folder):   ./build/cinema_server            -> http://localhost:8080
//                                        ./build/cinema_server 9000       -> http://localhost:9000
// Teacher-provided server code: students do not edit this file.

#include "httplib.h"
#include "routes.h"

#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <iostream>

#ifndef SERVER_MODE
#define SERVER_MODE "solution"
#endif

int main(int argc, char* argv[])
{
    int port = 8080;
    if (argc > 1)
    {
        port = std::atoi(argv[1]);
        if (port <= 0 || port > 65535)
        {
            std::cerr << "Port must be a number from 1 to 65535" << std::endl;
            return 1;
        }
    }

    std::ifstream page("web/index.html");
    if (!page)
    {
        std::cerr << "Cannot find web/index.html." << std::endl;
        std::cerr << "Start the server from the project folder, for example:  ./build/cinema_server" << std::endl;
        return 1;
    }

    httplib::Server server;
    server.set_mount_point("/", "./web");
    registerRoutes(server);

    std::cout << "Sunrise Cinema server (" << SERVER_MODE << " code)" << std::endl;
    std::cout << "Open http://localhost:" << port << " in your browser. Press Ctrl+C to stop." << std::endl;

    if (!server.listen("127.0.0.1", port))
    {
        std::cerr << "Could not start on port " << port << ". Is another program using it? Try: ./build/cinema_server 9000" << std::endl;
        return 1;
    }
    return 0;
}
